CREATE TABLE IF NOT EXISTS sep_urls(url TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS sep_contents(content_id TEXT PRIMARY KEY, representation TEXT NOT NULL CHECK(representation IN ('stored_metadata','provided_body')), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sep_versions(version_id TEXT PRIMARY KEY, url TEXT NOT NULL REFERENCES sep_urls, content_id TEXT NOT NULL REFERENCES sep_contents, published TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sep_occurrences(occurrence_id TEXT PRIMARY KEY, version_id TEXT NOT NULL REFERENCES sep_versions, source TEXT NOT NULL, pointer TEXT NOT NULL, observed_at TEXT, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sep_legacy_versions(revision_id TEXT REFERENCES revisions, version_id TEXT REFERENCES sep_versions, PRIMARY KEY(revision_id,version_id));
CREATE TABLE IF NOT EXISTS sep_event_mentions(event_id TEXT REFERENCES events, version_id TEXT REFERENCES sep_versions, role TEXT NOT NULL, scope_quote TEXT, verification TEXT NOT NULL CHECK(verification='imported_not_revalidated'), PRIMARY KEY(event_id,version_id,role));
CREATE TABLE IF NOT EXISTS sep_article_relations(left_version TEXT REFERENCES sep_versions, right_version TEXT REFERENCES sep_versions, relation TEXT NOT NULL CHECK(relation IN ('exact_saved_version','same_headline_time_candidate','similar_headline_candidate','no_duplicate_signal')), status TEXT NOT NULL CHECK(status IN ('saved_core_equal','unconfirmed')), payload TEXT NOT NULL, PRIMARY KEY(left_version,right_version,relation));
CREATE TABLE IF NOT EXISTS sep_review_records(record_hash TEXT PRIMARY KEY, sample_id TEXT NOT NULL, event_id TEXT REFERENCES events, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sep_fetch_observations(observation_id TEXT PRIMARY KEY, version_id TEXT NOT NULL REFERENCES sep_versions, result TEXT NOT NULL CHECK(result IN ('not_attempted','request_failed','deleted','empty_body','available','reported_deleted','reported_blank_display')), basis TEXT NOT NULL CHECK(basis IN ('legacy_metadata_only','operator_report','synthetic','provided_observation')), observed_at TEXT, reported_at TEXT, http_status INTEGER, body_content_id TEXT REFERENCES sep_contents, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sep_quote_documents(document_hash TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sep_quote_sources(document_hash TEXT REFERENCES sep_quote_documents, sample_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('reference','incoming')), event_id TEXT REFERENCES events, version_id TEXT REFERENCES sep_versions, checked_at TEXT, quotes TEXT NOT NULL, verification TEXT NOT NULL CHECK(verification IN ('not_provided','operator_text_not_source_verified')), PRIMARY KEY(document_hash,sample_id,role));
